					"outputTypeDefinition": "type AdminPublishedCommitRefRepairOutput = {\n\tdryRun: boolean\n\tscannedPackages: number\n\tconsistent: number\n\trepairable: number\n\tunrecoverable: number\n\trepaired: number\n\tfailed: number\n\tskippedUnpublished: number\n\t/** Packages skipped because their owner is mid-deletion or deleted. */\n\tskippedOwnerDeleting: number\n\t/** Resume cursor (saved_packages.id). Keep paging until null. */\n\tnextCursor: string | null\n\t/** Non-consistent packages, plus every requested package when packageIds is set. */\n\toutcomes: Array<{\n\tpackageId: string\n\townerUserId: string\n\tsourceId: string\n\tpublishedCommit: string | null\n\toutcome: \"consistent\" | \"repairable\" | \"unrecoverable\" | \"repaired\" | \"skipped_unpublished\" | \"skipped_owner_deleting\" | \"failed\"\n\tdefaultBranch?: string\n\tdefaultBranchHead?: string | null\n\trepairedCommit?: string\n\tmovedSessionIds?: Array<string>\n\tbackupKey?: string\n\terror?: string\n}>\n}"
