					"inputTypeDefinition": "type CredentialOrgGrantInput = {\n\t/** Credential id of a secret, OAuth connection, or MCP server in your personal org (secretList or credentialList there). */\n\tcredential_id: string\n\t/** Slug of the org. Defaults to the org this request is bound to when that is not your personal org. */\n\torg?: string\n}",
					"outputTypeDefinition": "type CredentialOrgGrantOutput = {\n\tcredential_id: string\n\tcredential_kind: \"secret\" | \"integration\" | \"mcp-server\"\n\tname: string\n\torg: {\n\tid: string\n\tslug: string\n}\n\t/** False when the credential was already granted to the org. */\n\tcreated: boolean\n}"
